  "fmt"
  "net"
)
func main() {
  addr, _ := net.ResolveUDPAddr("udp", "224.0.0.1:9999")
  conn, err := net.ListenMulticastUDP("udp", nil, addr)
  if err != nil {
    fmt.Println(err)
    return
  }
  defer conn.Close()
  fmt.Println("Listening on multicast:", addr)
}

